import openpyxl

wb = openpyxl.load_workbook('data/65afbc8a-89ca-4ad5-8d62-355bb401f61d.xlsx', data_only=True)
for sheet_name in wb.sheetnames:
    ws = wb[sheet_name]
    print(f'=== Sheet: {sheet_name} (rows={ws.max_row}, cols={ws.max_column}) ===')
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
        row_data = []
        for cell in row:
            fill = cell.fill
            fill_info = ''
            if fill.start_color and fill.start_color.rgb and fill.start_color.rgb != '00000000':
                fill_info = f' start_color={fill.start_color.rgb}'
            if fill.fgColor and fill.fgColor.rgb and fill.fgColor.rgb != '00000000':
                fill_info += f' fgColor={fill.fgColor.rgb}'
            row_data.append(f'{cell.coordinate}={cell.value!r}{fill_info}')
        print(' | '.join(row_data))
